  renderPrompt(validateCheckTemplate, {
    wt: '.',
    specPath: `${epicDir}/SPEC.md`,
    tasksPath: 'TASKS.md',
    testCommand,
  }),
  { label: 'validate-check', model: 'sonnet' },
)

